import {wordCount} from '../../lib/writing.ts';

type Outcome='changed'|'unchanged'|'blocked';
export type TextFixture={id:string;kind:string;text:string;expected:{natural:Outcome;concise:Outcome};neural?:boolean};
const changed={natural:'changed',concise:'changed'} as const;
const unchanged={natural:'unchanged',concise:'unchanged'} as const;
const blocked={natural:'blocked',concise:'blocked'} as const;
const repeated='The method utilizes repeated sampling to identify stable patterns across research groups.';
const repetitions=Math.floor(1200/wordCount(repeated));
const limitText=Array(repetitions).fill(repeated).join(' ')+' study'.repeat(1200-repetitions*wordCount(repeated));

// Authored test text, not experimental findings or citations to actual studies.
